const topicAliases={ds:'data structures',dsa:'data structures',os:'operating systems',dbms:'database management systems',cn:'computer networks','hash tables':'hashing','hash table':'hashing','hash maps':'hashing','hash map':'hashing',bfs:'graphs',dfs:'graphs',bst:'binary search trees'};
const normalizeTopic=value=>String(value??'').normalize('NFKC').toLowerCase().replace(/[^a-z0-9+]+/g,' ').trim();
export function searchBooksByTopic(query=''){
 const normalized=normalizeTopic(query),q=topicAliases[normalized]||normalized;
 const words=q.split(' ').filter(word=>word&&!['and','of','the','in'].includes(word));
 if(!words.length)return [];
 return resources.filter(r=>r.type==='BOOK').map(book=>{
  const topics=book.topics||[],text=normalizeTopic([book.subject,...topics].join(' ')).split(' ');
  const matches=words.every(word=>text.some(term=>term.startsWith(word)));
  const matchedTopics=topics.filter(topic=>words.some(word=>normalizeTopic(topic).split(' ').some(term=>term.startsWith(word))));
  const score=(normalizeTopic(book.subject)===q?100:0)+(topics.some(topic=>normalizeTopic(topic)===q)?20:0)+(normalizeTopic(book.title).includes(q)?10:0)+matchedTopics.length;
  return {...book,matchedTopics,score,matches};
 }).filter(book=>book.matches).sort((a,b)=>b.score-a.score||a.title.localeCompare(b.title));
}
export function filterResources({category='For You',query='',selectedSubjects=subjects.slice(0,3).map(s=>s.name),saved=null}={}){const type={'PYQs':'PYQ','Books':'BOOK','Research':'RESEARCH','E-Resources':'E-RESOURCE'}[category];const q=query.trim().toLowerCase();return resources.filter(r=>(!type||r.type===type)&&(category!=='My Subjects'||selectedSubjects.includes(r.subject))&&(!saved||saved.includes(r.id))&&(!q||[r.title,r.subtitle,r.subject,r.code,r.description,r.provider,...(r.topics||[])].filter(Boolean).join(' ').toLowerCase().includes(q)));}
